DROP TABLE IF EXISTS `registros`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `registros` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `territorio_id` bigint(20) unsigned NOT NULL,
  `publicador_id` bigint(20) unsigned NOT NULL,
  `fecha_salida` date NOT NULL,
  `fecha_entrada` date DEFAULT NULL,
  `entrada_prevista` date DEFAULT NULL,
  `notas` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `registros_territorio_id_foreign` (`territorio_id`),
  KEY `registros_publicador_id_foreign` (`publicador_id`),
  CONSTRAINT `registros_publicador_id_foreign` FOREIGN KEY (`publicador_id`) REFERENCES `publicadores` (`id`) ON DELETE CASCADE,
  CONSTRAINT `registros_territorio_id_foreign` FOREIGN KEY (`territorio_id`) REFERENCES `territorios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=357 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

